package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import android.net.Uri
import android.content.Intent
import android.app.Activity
import app.honorable.editor.PhotoPresetNamespace
import java.io.ByteArrayInputStream
import java.io.ByteArrayOutputStream
import java.io.OutputStream
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class SubtitleSaveRequestTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(1000,2000,"Caption")),captionSourceUri="content://synthetic/original-srt")));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"durationMs",5000);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 @Test fun pausedSubtitleExportReturnsBeforeWidgets(){val a=activity();set(a,"workspaceActive",false);call(a,"exportSubtitles");assertNull(get(a,"pendingRange"));assertEquals(false,get(a,"importing"))}

 private val destination=Uri.parse("content://synthetic/copy-srt")
 @Suppress("UNCHECKED_CAST") private fun request(a:HonorableVideoEditorActivity,code:Int=1000,bytes:ByteArray?=null,clips:List<VideoSegment>?=null):VideoSaveRequest {val p=get(a,"project")as VideoEditProject;set(a,"pendingRange",0L to 5000L);return VideoSaveRequest(code,call(a,"closeState")as VideoCloseState,EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,clips?:p.segments,p.soundtrack,call(a,"sourceUris")as Map<String,Uri>,call(a,"sourceDurations")as Map<String,Long>,get(a,"importedSources")as Map<String,VideoSource>,bytes?:VideoCaptions.exportSrt(clips?:p.segments)).also{set(a,"videoSaveRequest",it)}}
 private fun accept(a:HonorableVideoEditorActivity,code:Int=1000,ok:Int=Activity.RESULT_OK,uri:Uri?=destination)=call(a,"acceptVideoSaveResult",code,ok,uri?.let{Intent().setData(it)})
 private fun ready(a:HonorableVideoEditorActivity)=request(a).also{set(a,"workspaceActive",false);accept(a)}
 private fun rejected(action:()->Unit){try{action();fail("Expected rejection")}catch(_:IllegalArgumentException){}}
 @Test fun subtitlePayloadAndReturnedBytesAreDefensive(){val a=activity();val p=get(a,"project")as VideoEditProject;val data=VideoCaptions.exportSrt(p.segments);val expected=data.copyOf();val r=request(a,bytes=data);data.fill(0);r.subtitleBytes().fill(1);assertArrayEquals(expected,r.subtitleBytes());assertEquals(VideoSaveRequest.Kind.SUBTITLES,r.kind);assertEquals("application/x-subrip",r.kind.mime);assertEquals("Noble-captions-copy.srt",r.kind.filename)}
 @Test fun payloadBoundsAndRequiredKindDataAreEnforced(){rejected{request(activity(),bytes=ByteArray(0))};rejected{request(activity(),bytes=ByteArray(VideoCaptions.MAX_SRT_BYTES+1))};assertEquals(VideoCaptions.MAX_SRT_BYTES,request(activity(),bytes=ByteArray(VideoCaptions.MAX_SRT_BYTES)).subtitleBytes().size);val a=activity();val p=get(a,"project")as VideoEditProject;rejected{VideoSaveRequest(1000,VideoCloseState.capture(p,5000,0,null,null,true,false,"content://synthetic/video"),EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,p.segments,null,mapOf("primary" to Uri.parse("content://synthetic/video")),mapOf("primary" to 5000L),emptyMap(),VideoSaveRequest.Kind.SUBTITLES)}}
 @Test fun generatedPlaybackTimingAndOriginalProjectArePreserved(){val a=activity();val p=get(a,"project")as VideoEditProject;p.restore(p.segments.map{it.copy(speed=2f)});val old=p.segments;val prepared=VideoExportSnapshot.clips(old,0,1500,3000);val bytes=VideoCaptions.exportSrt(prepared);val r=request(a,clips=prepared,bytes=bytes);assertEquals(listOf(VideoCaption(0,250,"Caption")),VideoCaptions.parsePlaybackSrt(r.subtitleBytes(),750));assertSame(old,p.segments);assertFalse(p.canUndo)}
 @Test fun boundedWritePreservesAllBytesAndFlushesOnce(){val data=ByteArray(12001){(it%251).toByte()};val output=object:ByteArrayOutputStream(){var flushes=0;override fun flush(){flushes++;super.flush()}};VideoSubtitleDocuments.writeBounded(output,data){};assertArrayEquals(data,output.toByteArray());assertEquals(1,output.flushes)}
 @Test fun closedGuardStopsBeforeAnyWriteOrFlush(){val output=object:ByteArrayOutputStream(){var flushes=0;override fun flush(){flushes++}};try{VideoSubtitleDocuments.writeBounded(output,byteArrayOf(1)){error("Stopped")};fail("Ignored guard")}catch(e:IllegalStateException){assertEquals("Stopped",e.message)};assertEquals(0,output.size());assertEquals(0,output.flushes)}
 @Test fun cancellationBetweenChunksStopsPartialWriteBeforeFlush(){var current=true;val output=object:ByteArrayOutputStream(){var flushes=0;override fun write(buffer:ByteArray,offset:Int,length:Int){super.write(buffer,offset,length);current=false};override fun flush(){flushes++}};try{VideoSubtitleDocuments.writeBounded(output,ByteArray(12000)){check(current){"Stopped"}};fail("Ignored cancellation")}catch(_:IllegalStateException){};assertEquals(4096,output.size());assertEquals(0,output.flushes)}
 @Test fun outputFailurePropagatesWithoutFurtherWritesOrFlush(){val output=object:OutputStream(){var writes=0;var flushes=0;override fun write(value:Int){writes++;throw java.io.IOException("Provider failed")};override fun flush(){flushes++}};try{VideoSubtitleDocuments.writeBounded(output,ByteArray(5000)){};fail("Ignored failure")}catch(e:java.io.IOException){assertEquals("Provider failed",e.message)};assertEquals(1,output.writes);assertEquals(0,output.flushes)}
 @Test fun guardedReadStopsAfterOwnershipIsLostByProviderRead(){var current=true;val input=object:ByteArrayInputStream(ByteArray(12000)){var reads=0;override fun read(buffer:ByteArray,offset:Int,length:Int):Int{reads++;val count=super.read(buffer,offset,length);current=false;return count}};try{VideoSubtitleDocuments.readBounded(input){check(current){"Stopped"}};fail("Ignored cancellation")}catch(_:IllegalStateException){};assertEquals(1,input.reads)}
 @Test fun cleanupCannotDeleteBeforeSeparationOrAfterLosingOwner(){var deletes=0;assertFalse(VideoSubtitleDocuments.cleanupIfOwned(false,{fail("Unverified guard")}){deletes++;true});assertFalse(VideoSubtitleDocuments.cleanupIfOwned(true,{error("Closed")}){deletes++;true});assertEquals(0,deletes);assertTrue(VideoSubtitleDocuments.cleanupIfOwned(true,{}){deletes++;true});assertEquals(1,deletes)}
 @Test fun legacyReadAndWriteSignaturesRemainAvailable(){val methods=VideoSubtitleDocuments::class.java.methods;assertTrue(methods.any{it.name=="readBounded"&&it.parameterCount==1});assertTrue(methods.any{it.name=="writeCopy"&&it.parameterCount==4});assertArrayEquals(byteArrayOf(1,2,3),VideoSubtitleDocuments.readBounded(ByteArrayInputStream(byteArrayOf(1,2,3))))}
 @Test fun closedRequestGuardRunsBeforePoisonedAndroidContext(){val context=unsafe.allocateInstance(Activity::class.java)as Activity;try{VideoSubtitleDocuments.writeCopy(context,destination,byteArrayOf(1),setOf(Uri.parse("content://synthetic/original"))){error("Closed before provider")};fail("Reached provider")}catch(e:IllegalStateException){assertEquals("Closed before provider",e.message)}}
 @Test fun pausedSubtitleResultWaitsForForegroundWithoutWriting(){val a=activity();val r=ready(a);assertTrue(r.isReady);assertEquals(VideoSaveRequest.Kind.SUBTITLES,r.kind);assertEquals(false,get(a,"saving"));call(a,"resumeVideoSave");assertTrue(r.isReady);set(a,"workspaceActive",true);assertEquals(true,call(a,"canDispatchVideoSave",r))}
 @Test fun changedSourceModeMusicOrRecoveryRejectsBeforeWrite(){for(flag in listOf("source","mode","music","project","recovery","catalog")){val a=activity();val r=ready(a);val p=get(a,"project")as VideoEditProject;when(flag){"source"->set(a,"source",Uri.parse("content://synthetic/other"));"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"music"->p.setSoundtrack(VideoSoundtrack("content://synthetic/music",10000));"project"->set(a,"project",VideoEditProject(5000));"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"importedSources",linkedMapOf("extra" to VideoSource("extra","content://synthetic/extra",6000)))};set(a,"workspaceActive",true);call(a,"resumeVideoSave");assertTrue(flag,r.isClosed);assertNull(get(a,"videoSaveRequest"));assertEquals(false,get(a,"saving"))}}
 @Test fun subtitleCopyCannotTargetOriginalCaptionDocument(){val a=activity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val r=request(a);set(a,"workspaceActive",false);accept(a,uri=Uri.parse("content://synthetic/original-srt"));assertTrue(r.isClosed);assertNull(get(a,"videoSaveRequest"));assertSame(old,p.segments);assertFalse(p.canUndo)}
 @Test fun subtitleReleaseDoesNotClearEitherEncoderReference(){val a=activity();val r=ready(a);r.beginWriting();set(a,"saving",true);val audio=unsafe.allocateInstance(VideoAudioExporter::class.java)as VideoAudioExporter;val video=unsafe.allocateInstance(VideoCompositionExporter::class.java)as VideoCompositionExporter;set(a,"audioExporter",audio);set(a,"exporter",video);assertEquals(true,call(a,"releaseVideoSave",r));assertSame(audio,get(a,"audioExporter"));assertSame(video,get(a,"exporter"));assertEquals(false,get(a,"saving"))}
 @Test fun staleSubtitleReleaseCannotUnlockNewAudioOwner(){val a=activity();val old=ready(a);old.beginWriting();val p=get(a,"project")as VideoEditProject;set(a,"pendingRange",0L to 5000L);val current=VideoSaveRequest(1001,call(a,"closeState")as VideoCloseState,EditorAccessMode.GUEST_BASIC,PhotoPresetNamespace.GUEST,p.segments,null,mapOf("primary" to Uri.parse("content://synthetic/video")),mapOf("primary" to 5000L),emptyMap(),VideoSaveRequest.Kind.AUDIO);current.accept(1001,true,destination);current.beginWriting();set(a,"videoSaveRequest",current);set(a,"saving",true);assertEquals(false,call(a,"releaseVideoSave",old));assertSame(current,get(a,"videoSaveRequest"));assertEquals(true,get(a,"saving"))}
 @Test fun duplicateSubtitleReceiptCannotReplaceDestinationOrData(){val a=activity();val r=ready(a);val bytes=r.subtitleBytes();accept(a,uri=Uri.parse("content://synthetic/other"));assertSame(r,get(a,"videoSaveRequest"));assertArrayEquals(bytes,r.subtitleBytes());assertEquals(destination,r.beginWriting());assertNull(r.beginWriting())}
 @Test fun recreationDoesNotPersistCaptionBytesOrDestination(){val a=activity();set(a,"nextVideoSaveCode",1001);ready(a);val state=android.os.Bundle();call(a,"writeVideoSaveState",state);assertEquals(setOf("nextVideoSaveCode","videoSaveRequestCode","videoSaveHadDestination"),state.keySet());val restored=activity();call(restored,"restoreVideoSaveState",state);assertEquals(true,get(restored,"interruptedVideoSave"));assertNull(get(restored,"videoSaveRequest"));assertEquals(false,get(restored,"saving"))}
 @Test fun interruptedThreadStopsBeforeStreamWrite(){val output=ByteArrayOutputStream();try{Thread.currentThread().interrupt();try{VideoSubtitleDocuments.writeBounded(output,byteArrayOf(1)){};fail("Ignored interruption")}catch(_:java.io.InterruptedIOException){};assertEquals(0,output.size())}finally{Thread.interrupted()}}
}
